import{_ as t,o,c as r,a4 as s}from"./chunks/framework.kn7HWrZO.js";const u=JSON.parse('{"title":"Publish the Web UI behind a reverse proxy","description":"","frontmatter":{"editSource":"docs/user/guide/public-deployments.md","rawMarkdownPath":"en/guide/public-deployments.md"},"headers":[],"relativePath":"en/guide/public-deployments.md","filePath":"en/guide/public-deployments.md"}'),a={name:"en/guide/public-deployments.md"};function i(n,e,d,h,c,l){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="publish-the-web-ui-behind-a-reverse-proxy" tabindex="-1">Publish the Web UI behind a reverse proxy <a class="header-anchor" href="#publish-the-web-ui-behind-a-reverse-proxy" aria-label="Permalink to &quot;Publish the Web UI behind a reverse proxy&quot;">​</a></h1><p><code>dsh --profile web</code> serves the GUI on a loopback port, so a browser on another machine cannot reach it, and the process knows nothing about the address you do use. A reverse proxy in front of it owns that external leg — the public host name, TLS, and the path prefix it strips before forwarding to the listener — and <code>--public-url</code> tells DSH which address browsers use:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --public-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://app.example/ui/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trusted-host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.example</span></span></code></pre></div><h2 id="what-public-url-advertises" tabindex="-1">What <code>--public-url</code> advertises <a class="header-anchor" href="#what-public-url-advertises" aria-label="Permalink to &quot;What `--public-url` advertises&quot;">​</a></h2><p><code>--public-url</code> accepts an <code>http://</code> or <code>https://</code> root with an optional mount prefix and normalizes it to end in <code>/</code>. It supplies the printed and opened startup URL, <code>DSH_WEB_URL</code>, and the Web GUI URL in the agent&#39;s runtime context. The webserver keeps serving origin-root routes and never learns the mount. The <code>publicUrl</code> config field publishes the same advertisement.</p><h2 id="what-the-proxy-must-do" tabindex="-1">What the proxy must do <a class="header-anchor" href="#what-the-proxy-must-do" aria-label="Permalink to &quot;What the proxy must do&quot;">​</a></h2><ul><li><strong>Preserve the browser-facing <code>Host</code>.</strong> The fence compares the received <code>Host</code> against the accepted authorities, so the proxy forwards it unchanged instead of rewriting it to the listener&#39;s address.</li><li><strong>Strip the mount prefix.</strong> The listener answers origin-root routes, so a request for <code>/ui/api/...</code> must arrive as <code>/api/...</code>.</li><li><strong>Forward upgrades.</strong> Every request and WebSocket upgrade the page opens must reach the listener with its <code>Upgrade</code> and <code>Connection</code> headers intact; TLS terminates on the proxy&#39;s external leg when it serves HTTPS.</li><li><strong>Rewrite cookie scope.</strong> A backend serving plain HTTP issues host-only <code>Path=/</code> cookies without <code>Secure</code>; the proxy then rewrites <code>Path</code> to the mount (<code>/ui/</code>) and adds <code>Secure</code> on its HTTPS leg. A backend listener serving its own TLS already marks the cookie <code>Secure</code>, so the proxy only rewrites <code>Path</code>.</li><li><strong>Redirect the bare mount.</strong> <code>/ui/</code> is the only entry: it alone exchanges the launch token for the session cookie, and it or <code>/ui/index.html</code> serves the document to a browser that already holds that cookie, because the served document resolves URLs against its own directory. A request to <code>/ui</code> must arrive as <code>/ui/</code>, and the stripped backend cannot reconstruct that external path.</li></ul><h2 id="trust-the-authority-browsers-use" tabindex="-1">Trust the authority browsers use <a class="header-anchor" href="#trust-the-authority-browsers-use" aria-label="Permalink to &quot;Trust the authority browsers use&quot;">​</a></h2><p>The fence accepts loopback, the listener&#39;s own bind address, and every authority <code>--trusted-host</code> names. A browser that reaches the deployment under any other authority gets 403 for every API call, however correct the proxy is, so name the browser-visible authority with <code>--trusted-host</code>; advertising it with <code>--public-url</code> is display only and does not admit it. An entry without a port matches any port, which suits a tunnel that binds a different one each time. The fence only admits the request; the launch token in the printed URL and the signed session cookie authenticate it. TLS, wherever it terminates, changes none of this: the certificate identifies the server to the browser, not the browser to the server.</p><p>Neither the advertised URL nor the fence protects the listening port itself, so restrict the port to the trusted proxy or network.</p><h2 id="secure-the-external-leg" tabindex="-1">Secure the external leg <a class="header-anchor" href="#secure-the-external-leg" aria-label="Permalink to &quot;Secure the external leg&quot;">​</a></h2><p>Terminate TLS at the proxy, on the listener itself, or on both; <code>--public-url</code> remains an advertisement. An <code>http://</code> browser-facing root exposes the launch token in plaintext. An <code>https://</code> proxy root protects the browser-to-proxy leg; encryption between proxy and listener depends on the listener&#39;s TLS configuration.</p><p>To terminate on the listener, pass <code>--tls-cert</code> and <code>--tls-key</code>, each a path resolved against the process working directory: the certificate file holds the full chain and the key file an unencrypted PEM private key. DSH never obtains, renews, or watches certificates, and the carrier reads the files once, so replace them and reload the listener or restart the process to change them; startup fails on a missing or invalid pair and never falls back to HTTP. The browser applies its own trust store and name checks, so the certificate must cover the hostname or IP you open. The default port stays 3080. Native TLS needs no proxy, but proxy deployments and <code>--public-url</code> remain supported independently. A TLS listener marks session cookies <code>Secure</code>; keep the public browser-facing leg HTTPS so browsers can return those cookies.</p><p>The printed URL carries a process credential, so share it only with intended users.</p><p>The <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/bundle/web-app/README.md#public-deployments" target="_blank" rel="noreferrer">Web app reference</a> documents the <code>--public-url</code>, <code>--trusted-host</code>, and <code>--tls-cert</code>/<code>--tls-key</code> command-line options. In the Web profile, <code>publicUrl</code> configures the <code>web-runtime</code> row, <code>trustedHosts</code> configures the <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/client/connection/README.md" target="_blank" rel="noreferrer">Connection row</a>, and <code>tls</code> configures the <a href="./../reference/subsystems/web-server#config">webserver row</a>.</p>',15)])])}const b=t(a,[["render",i]]);export{u as __pageData,b as default};
